<script setup>
defineProps({ scenario: Object, role: String, actionMessage: String, buttonPermissionIds: { type: Array, default: () => [] } });
const emit = defineEmits(['launch', 'approve']);
const statusClass = (status) => status.includes('完成') || status.includes('创建') || status.includes('执行') || status.includes('批准') ? 'done' : status.includes('审批中') ? 'active' : 'waiting';
</script>
<template>
  <div v-if="scenario" class="page action-page"><div class="action-hero"><div><span class="eyebrow">BUSINESS ACTION CENTER · PROCUREMENT PLAYBOOK</span><h2>原料智能采购协同</h2><p>以一条受控业务意图，串联生产、库存、质量、供应商、预算、审批和 ERP 执行；AI 负责核算与编排，人负责高风险决策。</p></div><div class="action-status"><span>流程状态</span><b>{{ scenario.execution.status }}</b><small v-if="scenario.execution.requisitionId">{{ scenario.execution.requisitionId }}</small></div></div>
    <section class="action-intent panel"><div><span class="eyebrow">PROCUREMENT INTENT</span><h3>{{ scenario.intent.material }} <small>{{ scenario.intent.materialCode }}</small></h3><p>{{ scenario.intent.productionDemand }}</p></div><div class="intent-facts"><div><span>需求数量</span><b>{{ scenario.intent.requestedQty }} {{ scenario.intent.unit }}</b></div><div><span>要求到货</span><b>{{ scenario.intent.requiredDate }}</b></div><div><span>建议缺口</span><b class="highlight">{{ scenario.demand.shortage }} {{ scenario.intent.unit }}</b></div><div><span>最晚下单</span><b>{{ scenario.demand.latestOrderDate }}</b></div></div><div class="intent-actions"><button v-if="scenario.execution.status === '方案待发起' && buttonPermissionIds.includes('procurement.launch')" class="action-primary" @click="emit('launch')">一键发起采购协同</button><button v-else-if="scenario.execution.status === '审批中' && buttonPermissionIds.includes('procurement.approve')" class="action-primary" @click="emit('approve')">模拟批准并提交 ERP</button><button v-else-if="!['方案待发起','审批中'].includes(scenario.execution.status)" class="action-disabled" disabled>等待下一节点处理</button><small v-if="(scenario.execution.status === '方案待发起' && !buttonPermissionIds.includes('procurement.launch')) || (scenario.execution.status === '审批中' && !buttonPermissionIds.includes('procurement.approve'))">当前有效策略未授予此节点的操作按钮。</small><small>写入保护：{{ scenario.policy.writeGuard }}</small></div></section>
    <p v-if="actionMessage" class="procurement-message">{{ actionMessage }}</p>
    <section class="action-grid"><article class="panel procurement-checks"><div class="section-header"><div><span class="eyebrow">AI PREFLIGHT</span><h2>跨系统预检</h2></div><b>4 / 4 已完成</b></div><div v-for="check in scenario.checks" :key="check.name" class="check-row"><i :class="check.result === '关注' ? 'warn' : 'pass'"/><div><strong>{{ check.name }}</strong><p>{{ check.detail }}</p></div><span>{{ check.source }}</span><b :class="check.result === '关注' ? 'warn-text' : 'pass-text'">{{ check.result }}</b></div></article>
      <article class="panel supplier-plan"><div class="section-header"><div><span class="eyebrow">SUPPLIER DECISION</span><h2>供应商建议</h2></div><b>AI 推荐</b></div><div v-for="supplier in scenario.suppliers" :key="supplier.id" :class="['supplier-row', { recommended: supplier.recommendation === '推荐' }]"><div class="supplier-head"><strong>{{ supplier.name }}</strong><span>{{ supplier.recommendation }}</span></div><p>{{ supplier.reason }}</p><div class="supplier-stats"><span>单价 <b>¥{{ supplier.price }}/kg</b></span><span>交期 <b>{{ supplier.leadTime }} 天</b></span><span>评分 <b>{{ supplier.score }}</b></span></div></div></article></section>
    <section class="action-grid workflow-grid"><article class="panel workflow-panel"><div class="section-header"><div><span class="eyebrow">CONTROLLED WORKFLOW</span><h2>受控执行链</h2><p>每一步都带有来源系统、审批约束和可回放审计。</p></div></div><div class="workflow-steps"><div v-for="(step,index) in scenario.workflow" :key="step.id" :class="['workflow-step', statusClass(step.status)]"><span>{{ String(index + 1).padStart(2,'0') }}</span><div><strong>{{ step.name }}</strong><small>{{ step.system }}</small></div><b>{{ step.status }}</b></div></div></article>
      <article class="panel policy-panel"><span class="eyebrow">POLICY & APPROVAL</span><h2>审批与写入边界</h2><div class="policy-amount"><span>预计采购金额</span><b>¥{{ scenario.policy.estimatedAmount.toLocaleString() }}</b><small>预算阈值 ¥{{ scenario.policy.budgetLimit.toLocaleString() }}</small></div><div class="approval-route"><span v-for="(person,index) in scenario.policy.approvalRoute" :key="person"><b>{{ index + 1 }}</b>{{ person }}</span></div><div class="policy-guard"><b>KMS + 策略中心</b><p>仅使用本次采购任务的短时凭据调用 ERP；审批前禁止创建正式采购订单。</p></div></article>
    </section>
    <section class="panel procurement-audit"><div class="section-header"><div><span class="eyebrow">EXECUTION AUDIT</span><h2>业务审计与回写</h2></div><b>{{ scenario.audit.length }} 条记录</b></div><div v-for="(entry,index) in scenario.audit" :key="`${entry.time}-${index}`" class="procurement-audit-row"><time>{{ entry.time }}</time><strong>{{ entry.actor }} · {{ entry.action }}</strong><p>{{ entry.detail }}</p></div></section>
  </div><div v-else class="loading">正在加载采购协同模板…</div>
</template>
